358	// routeTaskHandoff routes the handoff of a task among the agents with a
359	// command for its access, the stopped agent excluded; it never waits.
360	func routeTaskHandoff(store posemodel.Store, prior posemodel.ReviewRun) (string, *posemodel.DelegationRoutingRecord, error) {
361		policy, _, found, err := store.LoadDelegationPolicy()
362		if err != nil {
363			return "", nil, err
364		}
365		if !found {
366			return "", nil, posemodel.ErrNoReviewerAdapter
367		}
368		agent, record, err := routeTask(store, policy, prior.Access, "auto", prior.Lead, prior.Adapter)
369		if err != nil {
370			return "", record, err
371		}
372		if record.Step == posemodel.DelegationStepWait {
373			return "", record, errors.New(tr("every other agent is limited until "+record.WaitUntil+"; hand off after the reset, or wait for this run's reset and resume it",
374				"todos os outros agentes estão limitados até "+record.WaitUntil+"; faça o handoff depois do reset, ou espere o reset deste run e o retome"))
375		}
376		return agent, record, nil
377	}
