379	// delegateTaskNextActions are the ways forward of a stopped task, judged by
380	// the planning their commands run (R9).
381	func delegateTaskNextActions(store posemodel.Store, a posemodel.DelegationAttempt, latest posemodel.ReviewRun) []delegateNextAction {
382		reason := func(err error) string { return strings.TrimPrefix(err.Error(), "pose: ") }
383		var actions []delegateNextAction
384		if i := latest.Interruption; latest.Status == posemodel.ReviewRunInterrupted && i != nil {
385			resume := delegateNextAction{Action: "resume", Command: "pose delegate resume " + a.AttemptID}
386			plan, err := store.PlanDelegationTaskResume(latest.RunID, "")
387			switch {
388			case !i.Resumable:
389				resume.Why = tr("the stop is not resumable", "a parada não é retomável")
390			case err != nil:
391				resume.Why = reason(err)
392			case plan.Existing != nil:
393				resume.Why = tr("the run was already continued", "o run já foi continuado")
394			}
395			if resume.Why == "" {
396				reset, resetErr := time.Parse(time.RFC3339Nano, i.ResetAt)
397				if i.ResetAt != "" && resetErr == nil && reset.After(time.Now()) {
398					wait := delegateNextAction{Action: "wait", Command: "pose delegate resume " + a.AttemptID + " --wait-until-reset"}
399					if _, err := posemodel.ReviewResumeDelay(latest, time.Now(), 24*time.Hour, 0); err != nil {
400						wait.Why = reason(err)
401					} else {
402						wait.Available = true
403					}
404					actions = append(actions, wait)
405					resume.Why = tr("the agent is limited until ", "o agente está limitado até ") + i.ResetAt
406				} else {
407					resume.Available = true
408				}
409			}
410			actions = append(actions, resume)
411		}
412		handoff := delegateNextAction{Action: "handoff", Command: "pose delegate handoff " + a.AttemptID + " --to auto"}
413		if agent, _, err := routeTaskHandoff(store, latest); err != nil {
414			handoff.Why = reason(err)
415		} else if plan, err := store.PlanDelegationTaskHandoff(latest.RunID, agent); err != nil {
416			handoff.Why = reason(err)
417		} else if plan.Existing != nil {
418			handoff.Why = tr("the run was already continued", "o run já foi continuado")
419		} else {
420			handoff.Available = true
421		}
422		return append(actions, handoff, delegateCancelAction())
423	}
